const items = $input.all();
const xml = (items[0].json.data || items[0].json.body || '').toString();
const baseUrl = $('Webhook').item.json.body.url || '';

// Extract URLs from sitemap XML
const urlMatches = xml.match(/<loc>(.*?)<\/loc>/gi) || [];
const urls = urlMatches.map(m => m.replace(/<\/?loc>/gi, '').trim());

// Categorize pages by URL path
const pages = urls.map(url => {
  const path = url.replace(baseUrl, '').replace(/^\//,'');
  const segments = path.split('/').filter(Boolean);
  const category = segments[0] || 'root';
  const slug = segments[segments.length - 1] || 'index';

  // Infer topic from URL slug
  const topic = slug.replace(/[-_]/g, ' ').replace(/\.(html|php|aspx)$/i, '').trim();

  return { url, path, category, slug, topic };
});

// Group by category
const categories = {};
for (const page of pages) {
  if (!categories[page.category]) categories[page.category] = [];
  categories[page.category].push(page);
}

const categorySummary = Object.entries(categories).map(([cat, pages]) => ({
  category: cat,
  pageCount: pages.length,
  topics: pages.map(p => p.topic).slice(0, 20)
}));

return [{
  json: {
    baseUrl,
    totalPages: pages.length,
    categoryCount: categorySummary.length,
    categories: categorySummary,
    allTopics: pages.map(p => p.topic).slice(0, 100),
    industry: $('Webhook').item.json.body.industry || 'general'
  }
}];
